import Foundation

/// Interface text. Chinese is the source language: the key *is* the Chinese text.
/// English and Japanese are in App/Resources/<lang>.lproj/Localizable.strings,
/// generated by tools/i18n.py from App/Resources/i18n/translations.json.
/// The app follows the system language (zh-Hans, en, ja; others get English).
enum Localization {
    /// Tests and the screenshot tool can render another language.
    static var bundle: Bundle = .main

    /// The bundle for one language, e.g. "en", "ja", "zh-Hans".
    static func bundle(for language: String) -> Bundle? {
        Bundle.main.path(forResource: language, ofType: "lproj").flatMap(Bundle.init(path:))
    }
}

/// Translated interface text for a Chinese source string.
func L(_ key: String) -> String {
    Localization.bundle.localizedString(forKey: key, value: key, table: nil)
}

/// Translated text from a given language's bundle (e.g. a prompt in the language just chosen).
func L(_ key: String, in bundle: Bundle) -> String {
    bundle.localizedString(forKey: key, value: key, table: nil)
}

/// Same, with printf-style arguments (%@, %d, %1$@ …).
func L(_ key: String, _ args: CVarArg...) -> String {
    String(format: L(key), arguments: args)
}
